     1	#!/usr/bin/env python3
     2	"""Compute deterministic profile-based bounds for the m5 method menu."""
     3	import json
     4	import math
     5	import os
     6	from pathlib import Path
     7	import re
     8	import sys
     9	
    10	
    11	METHODS = {
    12	    "data-parallel over inputs": ("whole", 8),
    13	    "batching": ("whole", 4),
    14	    "multi-GPU": ("compute", None),
    15	    "ensembles": ("whole", 8),
    16	    "pipelining": ("transfer", 2),
    17	}
    18	
    19	
    20	def number(value):
    21	    return type(value) in (int, float) and math.isfinite(value)
    22	
    23	
    24	def stage_kind(stage):
    25	    """Explicit kinds win; legacy names use fixed tokens, transfer before compute."""
    26	    if "kind" in stage:
    27	        if stage["kind"] not in ("compute", "transfer", "other"):
    28	            raise ValueError("invalid stage kind")
    29	        return stage["kind"]
    30	    tokens = set(re.findall(r"[a-z0-9]+", stage["stage"].lower()))
    31	    if tokens & {"transfer", "transfers", "h2d", "d2h", "htod", "dtoh", "copy", "memcpy", "upload", "download"}:
    32	        return "transfer"
    33	    if tokens & {"compute", "kernel", "kernels", "inference", "training", "forward", "backward"}:
    34	        return "compute"
    35	    return "other"
    36	
    37	
    38	def bounds(packet):
    39	    total = packet["total_wall_s"]
    40	    stages = packet["stages"]
    41	    gpus = packet.get("gpu_count", 1)
    42	    if (not number(total) or total <= 0 or not isinstance(stages, list) or not stages
    43	            or type(gpus) is not int or gpus < 0):
    44	        raise ValueError("invalid profile")
    45	    concurrency = packet.get("concurrency")
    46	    if concurrency is not None and not isinstance(concurrency, dict):
    47	        raise ValueError("invalid concurrency")
    48	    factor = concurrency.get("factor") if concurrency is not None else None
    49	    if factor is not None and not number(factor):
    50	        raise ValueError("invalid concurrency factor")
    51	    mps = concurrency.get("mps") if factor is not None else None
    52	    times = dict(compute=0.0, transfer=0.0, other=0.0)
    53	    mapping = []
    54	    for stage in stages:
    55	        if (not isinstance(stage, dict) or not isinstance(stage.get("stage"), str)
    56	                or not stage["stage"].strip() or not number(stage.get("wall_s")) or stage["wall_s"] < 0):
    57	            raise ValueError("invalid stage")
    58	        kind = stage_kind(stage)
    59	        util = stage.get("mean_gpu_util")
    60	        if util is not None and (not number(util) or not 0 <= util <= 1):
    61	            raise ValueError("invalid stage utilization")
    62	        times[kind] += stage["wall_s"]
    63	        mapping.append(dict(stage=stage["stage"], kind=kind,
    64	                            wall_fraction=min(1.0, stage["wall_s"] / total),
    65	                            mean_gpu_util=util,
    66	                            methods=[m for m, (k, _) in METHODS.items() if k in ("whole", kind)]))
    67	    if not all(math.isfinite(value) for value in times.values()):
    68	        raise ValueError("invalid stage times")
    69	    result = {}
    70	    for method, (kind, cap) in METHODS.items():
    71	        p = 1 if kind == "whole" else min(1.0, times[kind] / total)
    72	        if kind == "whole":
    73	            k = min(cap, factor) if factor is not None and factor >= 1 else 1
    74	            bound = k
    75	            derivation = dict(rule="min(fixed_cap, concurrency factor)", fixed_cap=cap,
    76	                              factor=factor, mps=mps)
    77	        else:
    78	            k = max(1, gpus) if cap is None else cap
    79	            amdahl = 1.0 / ((1.0 - p) + p / k)
    80	            bound = amdahl / k if cap is None else amdahl
    81	            derivation = (dict(rule="max(1, gpu_count)", gpu_count=gpus, amdahl=amdahl,
    82	                               cost_basis="equal_gpu_seconds") if cap is None else
    83	                          dict(rule="fixed_cap", fixed_cap=cap))
    84	        result[method] = dict(p=p, k=k, bound=bound, feasible=bound >= 1.05,
    85	                              k_derivation=derivation, stages=[s for s in mapping if method in s["methods"]])
    86	    return result
    87	
    88	
    89	def main():
    90	    if len(sys.argv) != 3:
    91	        print("usage: bounds.py <profile-packet.json> <out.json>", file=sys.stderr)
    92	        return 1
    93	    try:
    94	        result = bounds(json.loads(Path(sys.argv[1]).read_text()))
    95	        output = Path(sys.argv[2])
    96	        output.parent.mkdir(parents=True, exist_ok=True)
    97	        temporary = output.with_name(output.name + ".tmp")
    98	        temporary.write_text(json.dumps(result, allow_nan=False, indent=2) + "\n")
    99	        os.replace(temporary, output)
   100	        return 0
   101	    except (OSError, ValueError, TypeError, KeyError, OverflowError):
   102	        print("invalid profile input or output unavailable", file=sys.stderr)
   103	        return 1
   104	
   105	
   106	if __name__ == "__main__":
   107	    sys.exit(main())
